-- Die erweiterte Profilfreigabe gilt erst nach Annahme, niemals durch reine UI-Prüfungen.
begin;
create extension if not exists pgtap with schema extensions;
select set_config('search_path', 'public, extensions', true);
select no_plan();
insert into auth.users (id, email) values
  ('a1111111-0000-0000-0000-000000000001', 'privacy-sql-a@test.local'),
  ('b1111111-0000-0000-0000-000000000002', 'privacy-sql-b@test.local'),
  ('c1111111-0000-0000-0000-000000000003', 'privacy-sql-c@test.local');
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"a1111111-0000-0000-0000-000000000001","role":"authenticated"}', true);
insert into profiles (display_name, bio, height_cm) values ('Anna', 'Geschützte Bio', 175);
insert into body_measurements (measured_on, weight_kg) values ('2026-11-08', 70);
insert into meals(id, consumed_on, title) values ('a3333333-0000-0000-0000-000000000001', '2026-11-08', 'Private Mahlzeit');
select is((select count(*)::int from body_measurements where user_id = auth.uid()), 1, 'Eigentümer sieht seine Körperdaten weiterhin');
select is((select count(*)::int from meals where user_id = auth.uid()), 1, 'Eigentümer sieht seine Ernährung weiterhin');
select is((select count(*)::int from social_profiles where user_id = auth.uid()), 0, 'Ohne eigene Freigabe ist niemand auffindbar');
select public.enable_social_profile();
select is((select is_private from social_profiles where user_id = auth.uid()), true, 'Neue Konten sind privat');
update social_profiles set username = 'anna' where user_id = auth.uid();
select is((select display_name from social_profiles where user_id = auth.uid()), 'Anna', 'Der Basisname bleibt synchron');
select throws_ok($$update social_profiles set username = 'Anna' where user_id = auth.uid()$$, '23514', null, 'Benutzernamen werden nur normalisiert gespeichert');
select is((select count(*)::int from shared_profile_overviews where user_id = auth.uid()), 1, 'Eigentümer sieht seine Übersicht');
select set_config('request.jwt.claims', '{"sub":"b1111111-0000-0000-0000-000000000002","role":"authenticated"}', true);
insert into profiles (display_name) values ('Ben');
select public.enable_social_profile();
select throws_ok($$update social_profiles set username = 'anna' where user_id = auth.uid()$$, '23505', null, 'Benutzername ist global eindeutig');
select is((select count(*)::int from social_profiles where username = 'anna'), 1, 'Sichtbare Konten sind nach Benutzername auffindbar');
select is((select count(*)::int from shared_profile_overviews where user_id = 'a1111111-0000-0000-0000-000000000001'), 0, 'Fremde sehen keine geschützte Übersicht');
select is((select count(*)::int from profiles where user_id = 'a1111111-0000-0000-0000-000000000001'), 0, 'Quellprofile behalten Owner-RLS');
insert into follows (followed_user_id) values ('a1111111-0000-0000-0000-000000000001');
select is((select status from follows where user_id = auth.uid()), 'pending', 'Privat folgen legt eine Anfrage an');
select is_empty($$update follows set status = 'accepted' where user_id = auth.uid() returning user_id$$, 'Anfragende können nicht selbst annehmen');
select is((select count(*)::int from shared_profile_overviews where user_id = 'a1111111-0000-0000-0000-000000000001'), 0, 'Offene Anfrage schaltet keine Daten frei');
select set_config('request.jwt.claims', '{"sub":"a1111111-0000-0000-0000-000000000001","role":"authenticated"}', true);
update follows set status = 'accepted' where followed_user_id = auth.uid();
select is((select status from follows where followed_user_id = auth.uid()), 'accepted', 'Nur Empfänger nimmt Anfrage an');
select set_config('request.jwt.claims', '{"sub":"b1111111-0000-0000-0000-000000000002","role":"authenticated"}', true);
select is((select overview->'profile'->>'bio' from shared_profile_overviews where user_id = 'a1111111-0000-0000-0000-000000000001'), 'Geschützte Bio', 'Angenommener Follower sieht die soziale Profilübersicht');
select is((select overview ? 'measurements' from shared_profile_overviews where user_id = 'a1111111-0000-0000-0000-000000000001'), false, 'Auch angenommene Follower erhalten keinen Messungsbereich');
select is((select overview ? 'meals' from shared_profile_overviews where user_id = 'a1111111-0000-0000-0000-000000000001'), false, 'Auch angenommene Follower erhalten keinen Ernährungsbereich');
select is((select (overview->'profile') ?| array['heightCm', 'targetWeightKg', 'sex', 'birthYear', 'activityLevel'] from shared_profile_overviews where user_id = 'a1111111-0000-0000-0000-000000000001'), false, 'Die soziale Profilprojektion enthält keine Körper- oder Berechnungsgrundlagen');
select is((select count(*)::int from body_measurements where user_id = 'a1111111-0000-0000-0000-000000000001'), 0, 'Auch nach Annahme bleibt die Quelltabelle owner-only');
select is((select count(*)::int from meals where user_id = 'a1111111-0000-0000-0000-000000000001'), 0, 'Ernährungsquellen bleiben nach Annahme owner-only');
delete from follows where user_id = auth.uid();
select is((select count(*)::int from shared_profile_overviews where user_id = 'a1111111-0000-0000-0000-000000000001'), 0, 'Entfolgen entzieht Zugriff sofort');
insert into follows (followed_user_id, status) values ('a1111111-0000-0000-0000-000000000001', 'accepted');
select is((select status from follows where user_id = auth.uid()), 'pending', 'Direkter Insert kann private Annahme nicht fälschen');
select set_config('request.jwt.claims', '{"sub":"a1111111-0000-0000-0000-000000000001","role":"authenticated"}', true);
delete from follows where followed_user_id = auth.uid();
select is((select count(*)::int from follows where followed_user_id = auth.uid()), 0, 'Empfänger kann Anfrage ablehnen');
update social_profiles set is_private = false where user_id = auth.uid();
select set_config('request.jwt.claims', '{"sub":"b1111111-0000-0000-0000-000000000002","role":"authenticated"}', true);
select is((select count(*)::int from shared_profile_overviews where user_id = 'a1111111-0000-0000-0000-000000000001'), 0, 'Auch öffentliche Konten zeigen Fremden nur die Basisidentität');
insert into follows (followed_user_id) values ('a1111111-0000-0000-0000-000000000001');
select is((select status from follows where user_id = auth.uid()), 'accepted', 'Öffentlich folgen wird sofort angenommen');
select is((select count(*)::int from shared_profile_overviews where user_id = 'a1111111-0000-0000-0000-000000000001'), 1, 'Öffentlich folgen schaltet Übersicht frei');
select set_config('request.jwt.claims', '{"sub":"c1111111-0000-0000-0000-000000000003","role":"authenticated"}', true);
insert into profiles (display_name) values ('Cem');
select public.enable_social_profile();
select is((select count(*)::int from shared_profile_overviews where user_id = 'a1111111-0000-0000-0000-000000000001'), 0, 'Unbeteiligte erhalten keinen Zugriff durch fremde Annahme');
select throws_ok('select bio from social_directory', '42703', null, 'Kontoverzeichnis enthält keine Bio');
select set_config('request.jwt.claims', '{"sub":"a1111111-0000-0000-0000-000000000001","role":"authenticated"}', true);
update social_profiles set is_private = true where user_id = auth.uid();
select is((select status from follows where followed_user_id = auth.uid()), 'accepted', 'Privatwechsel erhält bestehende angenommene Beziehungen');
select set_config('request.jwt.claims', '{"sub":"c1111111-0000-0000-0000-000000000003","role":"authenticated"}', true);
insert into follows(followed_user_id) values ('a1111111-0000-0000-0000-000000000001');
select is((select status from follows where user_id = auth.uid()), 'pending', 'Neue Anfragen brauchen nach Privatwechsel erneut Annahme');
select set_config('request.jwt.claims', '{"sub":"a1111111-0000-0000-0000-000000000001","role":"authenticated"}', true);
update social_profiles set is_private = false where user_id = auth.uid();
select is((select count(*)::int from follows where followed_user_id = auth.uid() and status = 'pending'), 0, 'Öffentlichwechsel nimmt offene Anfragen atomar an');
select set_config('request.jwt.claims', '{"sub":"c1111111-0000-0000-0000-000000000003","role":"authenticated"}', true);
select is((select count(*)::int from shared_profile_overviews where user_id = 'a1111111-0000-0000-0000-000000000001'), 1, 'Öffentlichwechsel gibt bestätigten Anfragen Zugriff');
select is_empty($$update body_measurements set weight_kg = 90 where user_id = 'a1111111-0000-0000-0000-000000000001' returning user_id$$, 'Follower erhalten keine fremden Schreibrechte');
select throws_ok($$update shared_profile_overviews set overview = '{}'::jsonb$$, '0A000', null, 'Freigegebene Übersicht ist nicht beschreibbar');
select is(has_table_privilege('authenticated', 'public.shared_profile_overviews', 'UPDATE'), false, 'Auch schreibbare Basisspalten der Ansicht haben keine Update-Rechte');
reset role;
set local role anon;
select throws_ok('select * from shared_profile_overviews', '42501', null, 'Anonyme sehen keine Übersicht');
select throws_ok('select * from social_directory', '42501', null, 'Anonyme sehen kein Kontoverzeichnis');
reset role;
select * from finish();
rollback;
